import { z } from 'zod';
import {
  ASSET_CATEGORIES,
  ASSET_OWNERSHIPS,
  ASSET_STATUSES,
  METER_TYPES,
  type AssetCategory,
  type AssetOwnership,
  type AssetStatus,
  type MeterType,
} from '../enums';
import {
  enumField,
  optionalDate,
  optionalInt,
  optionalMoney,
  optionalQty,
  optionalText,
  queryBoolean,
  requiredText,
} from './common';
import { paginationQuerySchema } from './pagination';

/** Asset code: AST-NNN (generated by the API). */
export const ASSET_CODE_REGEX = /^AST-\d{3,}$/;

/** Categories that are usually road vehicles (suggests vehicle documents). */
export const VEHICLE_CATEGORIES: readonly AssetCategory[] = [
  'JCB_BACKHOE',
  'TIPPER',
  'CAB',
  'TRACTOR',
  'WATER_BOWSER',
];

const registrationNo = z
  .string()
  .trim()
  .max(30, 'TOO_LONG')
  .nullable()
  .optional()
  .transform((v) =>
    v === undefined ? undefined : v ? v.replace(/\s+/g, ' ').toUpperCase() : null,
  );

const assetFields = z.object({
  name: requiredText(200),
  category: enumField(ASSET_CATEGORIES),
  make: optionalText(100),
  model: optionalText(100),
  registrationNo,
  chassisNo: optionalText(100),
  engineNo: optionalText(100),
  yearOfManufacture: optionalInt(1950, 2100),
  purchaseDate: optionalDate,
  purchaseCost: optionalMoney,
  ownership: enumField(ASSET_OWNERSHIPS).optional(),
  status: enumField(ASSET_STATUSES).optional(),
  meterType: enumField(METER_TYPES).optional(),
  currentMeter: optionalQty,
  serviceIntervalMeter: optionalQty,
  lastServiceMeter: optionalQty,
  internalRatePerHour: optionalMoney,
  internalRatePerDay: optionalMoney,
  isVehicle: z.boolean().optional(),
  notes: optionalText(2000),
});

export const assetCreateSchema = assetFields;
export type AssetCreateInput = z.input<typeof assetCreateSchema>;
export type AssetCreate = z.output<typeof assetCreateSchema>;
export const assetUpdateSchema = assetFields.partial();
export type AssetUpdate = z.output<typeof assetUpdateSchema>;

export const assetListQuerySchema = paginationQuerySchema.extend({
  category: z.enum(ASSET_CATEGORIES).optional(),
  status: z.enum(ASSET_STATUSES).optional(),
  isVehicle: queryBoolean,
});
export type AssetListQuery = z.infer<typeof assetListQuerySchema>;

export interface AssetDto {
  id: string;
  code: string;
  name: string;
  category: AssetCategory;
  make: string | null;
  model: string | null;
  registrationNo: string | null;
  chassisNo: string | null;
  engineNo: string | null;
  yearOfManufacture: number | null;
  purchaseDate: string | null;
  purchaseCost: string | null;
  ownership: AssetOwnership;
  status: AssetStatus;
  meterType: MeterType;
  currentMeter: string;
  serviceIntervalMeter: string | null;
  lastServiceMeter: string | null;
  internalRatePerHour: string | null;
  internalRatePerDay: string | null;
  isVehicle: boolean;
  notes: string | null;
  createdAt: string;
  updatedAt: string;
  /** Earliest expiry date among the current versions of the asset's documents. */
  nextExpiry: string | null;
}
